ALTER TABLE "reporting_officer_assignments" ADD CONSTRAINT "reporting_officer_assignments_activated_at_check" CHECK ("reporting_officer_assignments"."state" <> 'activated' or "reporting_officer_assignments"."activated_at" is not null);--> statement-breakpoint
ALTER TABLE "reporting_officer_assignments" ADD CONSTRAINT "reporting_officer_assignments_replaced_at_check" CHECK (("reporting_officer_assignments"."state" = 'replaced') = ("reporting_officer_assignments"."replaced_at" is not null));--> statement-breakpoint
ALTER TABLE "reporting_officer_assignments" ADD CONSTRAINT "reporting_officer_assignments_replaced_by_check" CHECK ("reporting_officer_assignments"."replaced_by" is null or ("reporting_officer_assignments"."state" = 'replaced' and "reporting_officer_assignments"."replaced_by" <> "reporting_officer_assignments"."id"));